//! Wireshark's value-string labels, generated by `scripts/gen_labels.py` from `tshark -G values`
//! of TShark (Wireshark) 4.7.4; TShark (Wireshark) 4.6.6. Do not edit by hand.
//!
//! The labels are Wireshark's text (Wireshark is GPL-2.0-or-later); filters accept them in place
//! of numbers, case-insensitively, as Wireshark does. Boolean fields map their labels to 1 and 0.
//! The table is the union of the versions above; a label that means different values is
//! ambiguous, and the checker rejects it.

use crate::fields::Field;

/// The `(label, value)` pairs of a field, in Wireshark's order; empty when it has none.
pub(crate) fn labels(f: Field) -> &'static [(&'static str, u64)] {
    match f {
        Field::EthType => ETH_TYPE,
        Field::VlanPriority => VLAN_PRIORITY,
        Field::VlanDei => BOOL_ELIGIBLE,
        Field::VlanEtype => ETH_TYPE,
        Field::ArpHwType => ARP_HW_TYPE,
        Field::ArpProtoType => ETH_TYPE,
        Field::ArpOpcode => ARP_OPCODE,
        Field::IpDsfieldDscp => IP_DSFIELD_DSCP,
        Field::IpDsfieldEcn => IP_DSFIELD_ECN,
        Field::IpFlagsRb => BOOL_SET,
        Field::IpFlagsDf => BOOL_SET,
        Field::IpFlagsMf => BOOL_SET,
        Field::IpProto => IP_PROTO,
        Field::Ipv6TclassDscp => IP_DSFIELD_DSCP,
        Field::Ipv6TclassEcn => IP_DSFIELD_ECN,
        Field::Ipv6Nxt => IP_PROTO,
        Field::Ipv6FraghdrMore => BOOL_YES,
        Field::TcpFlagsRes => BOOL_SET,
        Field::TcpFlagsAe => BOOL_SET,
        Field::TcpFlagsCwr => BOOL_SET,
        Field::TcpFlagsEce => BOOL_SET,
        Field::TcpFlagsUrg => BOOL_SET,
        Field::TcpFlagsAck => BOOL_SET,
        Field::TcpFlagsPush => BOOL_SET,
        Field::TcpFlagsReset => BOOL_SET,
        Field::TcpFlagsSyn => BOOL_SET,
        Field::TcpFlagsFin => BOOL_SET,
        Field::IcmpType => ICMP_TYPE,
        Field::Icmpv6Type => ICMPV6_TYPE,
        _ => &[],
    }
}

